 63 |     // initializer
 64 |     /// @dev initialize the contract, set the ERC721's name and symbol, and set the init core address
 65 |     /// @param _name ERC721's name
 66 |     /// @param _symbol ERC721's symbol
 67 |     /// @param _core core address
 68 |     function initialize(string calldata _name, string calldata _symbol, address _core, uint8 _maxCollCount)
 69 |         external
 70 |         initializer
 71 |     {
 72 |         __ERC721_init(_name, _symbol);
 73 |         core = _core;
 74 |         maxCollCount = _maxCollCount;
 75 |         emit SetMaxCollCount(_maxCollCount);
 76 |     }
 77 | 
 78 |     // functions
 79 |     /// @inheritdoc IPosManager
 80 |     function getPosBorrInfo(uint _posId) external view returns (address[] memory pools, uint[] memory debtShares) {
 81 |         PosBorrInfo storage posBorrInfo = __posBorrInfos[_posId];
 82 |         pools = posBorrInfo.pools.values();
 83 |         debtShares = new uint[](pools.length);
 84 |         for (uint i; i < pools.length; i = i.uinc()) {
 85 |             debtShares[i] = posBorrInfo.debtShares[pools[i]];
 86 |         }
 87 |     }
 88 | 
 89 |     /// @inheritdoc IPosManager
 90 |     function getPosBorrExtraInfo(uint _posId, address _pool)
 91 |         external
 92 |         view
 93 |         returns (uint totalInterest, uint lastDebtAmt)
 94 |     {
 95 |         PosBorrExtraInfo memory borrExtraInfo = __posBorrInfos[_posId].borrExtraInfos[_pool];
 96 |         totalInterest = borrExtraInfo.totalInterest;
 97 |         lastDebtAmt = borrExtraInfo.lastDebtAmt;
 98 |     }
 99 | 
100 |     /// @inheritdoc IPosManager
101 |     function getPosCollInfo(uint _posId)
102 |         external
103 |         view
104 |         returns (
105 |             address[] memory pools,
106 |             uint[] memory amts,
107 |             address[] memory wLps,
108 |             uint[][] memory ids,
109 |             uint[][] memory wLpAmts
110 |         )
111 |     {
112 |         PosCollInfo storage posCollInfo = __posCollInfos[_posId];
113 |         pools = posCollInfo.collTokens.values();
114 |         amts = new uint[](pools.length);
115 |         for (uint i; i < pools.length; i = i.uinc()) {
